import sys

def longest_palindrome_prefix_suffix(s):
    n = len(s)
    dp = [[0] * n for _ in range(n)]

    # Every single character is a palindrome of length 1
    for i in range(n):
        dp[i][i] = 1

    # Build the table. The gap represents the length of the substring.
    for gap in range(1, n):
        for i in range(n - gap):
            j = i + gap
            if s[i] == s[j]:
                dp[i][j] = dp[i + 1][j - 1] + 2
            else:
                dp[i][j] = max(dp[i + 1][j], dp[i][j - 1])

    # Now, we need to find the longest palindromic subsequence that is also a prefix and suffix
    max_length = 0
    result = ""
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            if dp[i][j] == length and s.startswith(s[i:j+1]) and s.endswith(s[i:j+1]):
                if length > max_length:
                    max_length = length
                    result = s[i:j+1]

    return result

